[[nodiscard]] inline bool inTable(const Range* table, const size_t count, const uint32_t cp) {
  // Binary search: the tables are sorted and coalesced by the generator.
  size_t lo = 0;
  size_t hi = count;
  while (lo < hi) {
    const size_t mid = lo + (hi - lo) / 2;
    if (cp < table[mid].lo) {
      hi = mid;
    } else if (cp > table[mid].hi) {
      lo = mid + 1;
    } else {
      return true;
    }
  }
  return false;
}

